  'This course is an early health-sciences statistics requirement focused on clinical interpretation. Students learn to describe health data, reason about probability, risk, and diagnostic tests, compare groups, estimate effects with confidence intervals, and interpret hypothesis tests without reducing evidence to a single p-value. The course also covers regression, survival analysis, reproducible software, and critical appraisal of health research.',
  $shsjson${"slug": "statistics-for-health-sciences", "title": "Statistics for Health Sciences", "description": "This course is an early health-sciences statistics requirement focused on clinical interpretation. Students learn to describe health data, reason about probability, risk, and diagnostic tests, compare groups, estimate effects with confidence intervals, and interpret hypothesis tests without reducing evidence to a single p-value. The course also covers regression, survival analysis, reproducible software, and critical appraisal of health research.", "topics": [{"id": "e2669725-758a-477f-91bf-7886fb20d9ef", "type": "topic", "title": "Statistical Thinking for Health Sciences and Evidence-Based Practice", "description": "Introduces statistics as a clinical reasoning tool for describing health data, evaluating evidence, and improving care.", "children": [{"id": "f1e8264c-03af-4561-adda-e1163d43f314", "type": "subtopic", "title": "Why Statistics Matters in Health", "description": "Students learn that statistics helps clinicians separate signal from noise in patient care, quality improvement, and research.", "children": [{"id": "5396f757-d888-46e5-a370-024bfc3cea8d", "type": "concept", "title": "Evidence-based practice"}, {"id": "b7f17e11-bd81-478f-9cc0-8678ceb922c3", "type": "concept", "title": "Clinical uncertainty"}, {"id": "ca2052c9-1b1a-4edf-b31b-0d3084aaf19d", "type": "concept", "title": "Population variability"}, {"id": "795c29a5-ac71-4826-bcdb-658b4141b63f", "type": "concept", "title": "Decision-making under uncertainty"}, {"id": "9c0c28ab-b2ce-4899-ad22-953ab4357241", "type": "concept", "title": "Research literacy"}]}, {"id": "0b7b7407-6c83-4f60-88ba-47ba708391a4", "type": "subtopic", "title": "Questions Statistics Can Answer", "description": "This subtopic frames statistical methods around practical health questions.", "children": [{"id": "fcad387e-15bc-4774-8a4f-0e983ac3ad7f", "type": "concept", "title": "Description"}, {"id": "be9a9950-251a-43b0-8452-d534d80bfd27", "type": "concept", "title": "Estimation"}, {"id": "0e4386b6-960b-40de-9f86-020f6393a379", "type": "concept", "title": "Comparison"}, {"id": "4089ccdc-7d3c-40c8-a367-5a2a29189efe", "type": "concept", "title": "Association"}, {"id": "aa208158-a3b6-45f0-9c45-761c389494ba", "type": "concept", "title": "Prediction"}]}, {"id": "4a7ec1ce-8701-425b-af34-6d1c2071e58a", "type": "subtopic", "title": "Responsible Interpretation", "description": "Students learn to interpret results cautiously and clinically.", "children": [{"id": "8d0864f7-6d16-4994-8b2b-dc673da3f890", "type": "concept", "title": "Statistical significance"}, {"id": "f128078e-9693-44af-8185-00c486166b57", "type": "concept", "title": "Clinical significance"}, {"id": "6115d6ef-fd29-41e3-867b-15fbb28176b1", "type": "concept", "title": "Practical significance"}, {"id": "a370c682-3dd2-45d8-ab48-9f617e6090d4", "type": "concept", "title": "Replication"}, {"id": "362d1a6b-6076-488f-81f4-9093a19f4584", "type": "concept", "title": "Transparency"}]}]}, {"id": "ca177f5c-3ea2-41c6-bb09-c2c033037bfb", "type": "topic", "title": "Health Data Types, Measurement, Data Quality, and Study Variables", "description": "Builds fluency in variable types, measurement scales, clinical data quality, and dataset structure.", "children": [{"id": "816c88ba-9da3-4256-8e9c-9079c6f3089e", "type": "subtopic", "title": "Types of Variables", "description": "Students learn how variable type determines summaries, graphs, and tests.", "children": [{"id": "65f6bbeb-75ee-470a-99dd-e9000fecabe4", "type": "concept", "title": "Categorical variables"}, {"id": "e1bda85b-d56a-400b-83e9-e28921556312", "type": "concept", "title": "Binary variables"}, {"id": "9213ced4-391c-40ec-ae99-98e2c9ebf894", "type": "concept", "title": "Ordinal variables"}, {"id": "4f12d47d-91a8-4bbc-96cf-d35853294782", "type": "concept", "title": "Continuous variables"}, {"id": "c280aa57-4d4e-4c12-a03f-293fed3852c1", "type": "concept", "title": "Count variables"}]}, {"id": "cc341016-d201-48be-b67a-5dd90d3e6668", "type": "subtopic", "title": "Measurement and Data Quality", "description": "This subtopic covers reliability and trustworthiness of health data.", "children": [{"id": "dd749450-8d78-4935-a782-a9981e55b70f", "type": "concept", "title": "Validity"}, {"id": "ddb85441-d2b2-4a34-8623-911d56b6ff4c", "type": "concept", "title": "Reliability"}, {"id": "f04a67e2-795c-491b-86c0-22877c43676b", "type": "concept", "title": "Missing data"}, {"id": "86e9f3fb-0ac6-42d7-825c-22935863dece", "type": "concept", "title": "Outliers"}, {"id": "b3e1a805-9495-44c6-a056-f1ddbb084040", "type": "concept", "title": "Data cleaning"}]}, {"id": "2ea69188-62e5-406a-ab3c-863c8b521c17", "type": "subtopic", "title": "Dataset Structure", "description": "Students understand the basic anatomy of a health dataset.", "children": [{"id": "28391e3a-c8ac-4540-a370-e2e68e61a3ed", "type": "concept", "title": "Rows and observations"}, {"id": "cdcad10b-6ee2-4142-8949-dce832e95de6", "type": "concept", "title": "Columns and variables"}, {"id": "64e1c9ed-fc1c-486f-b9f5-256eff3bfd2f", "type": "concept", "title": "Codebook"}, {"id": "67830f36-c2f1-436a-bce8-8a7b28200bbc", "type": "concept", "title": "Data dictionary"}, {"id": "b24980cc-657b-47f3-8bff-e5346d951df9", "type": "concept", "title": "De-identified data"}]}]}, {"id": "a1d59972-ad1c-4796-9604-fd2f15144a18", "type": "topic", "title": "Descriptive Statistics, Tables, and Health Data Visualization", "description": "Develops tools for summarizing distributions, comparing groups, and communicating health data clearly.", "children": [{"id": "4fdcb923-5906-4418-9438-ea027e7317c1", "type": "subtopic", "title": "Measures of Center and Spread", "description": "Students summarize health variables in ways that match their distribution.", "children": [{"id": "030ca108-d9be-4644-8c16-e00df78de9bd", "type": "concept", "title": "Mean"}, {"id": "2e8095a6-08be-47b5-b5b0-7c42d21eae68", "type": "concept", "title": "Median"}, {"id": "f4ca71