set
  title = 'Statistics for Health Sciences',
  goal = 'Statistics for Health Sciences',
  summary = 'This course is an early health-sciences statistics requirement focused on clinical interpretation. Students learn to describe health data, reason about probability, risk, and diagnostic tests, compare groups, estimate effects with confidence intervals, and interpret hypothesis tests without reducing evidence to a single p-value. The course also covers regression, survival analysis, reproducible software, and critical appraisal of health research.',
