ept", "title": "Risk ratio CI"}, {"id": "7880dc36-e5b5-4cf9-8640-f9001e2cef45", "type": "concept", "title": "Odds ratio CI"}, {"id": "9a56877a-d3f8-4e42-a887-a75764ed577f", "type": "concept", "title": "Rate CI"}]}, {"id": "95a6b29a-e5d4-4d8d-876b-7906276a456a", "type": "subtopic", "title": "Clinical Interpretation", "description": "Students learn to read intervals for decision relevance.", "children": [{"id": "8df767cf-717c-4d1f-96cf-6b7908966c35", "type": "concept", "title": "Null value"}, {"id": "65bf9bff-21d6-4017-8cbc-e23170915e3e", "type": "concept", "title": "Width of interval"}, {"id": "3da7a060-5763-47f4-9be2-456589e963d2", "type": "concept", "title": "Direction of effect"}, {"id": "e491f57b-b564-4331-9b7f-ec88472672b4", "type": "concept", "title": "Plausible values"}, {"id": "9fcc7a1f-4b57-4b2b-a1b6-2507882416ba", "type": "concept", "title": "Minimal clinically important difference"}]}]}, {"id": "7c48f7d3-fa5b-441e-8b1e-49655a23a4ae", "type": "topic", "title": "Hypothesis Testing, p-Values, Type I/II Error, and Statistical Power", "description": "Develops responsible test interpretation without reducing evidence to a single p-value.", "children": [{"id": "66f8a803-57d1-4764-b701-4eb6394f51ac", "type": "subtopic", "title": "Testing Framework", "description": "Students learn the logic behind formal statistical tests.", "children": [{"id": "c8c8fe7d-5f2e-4ed9-858b-273686f8b0f5", "type": "concept", "title": "Null hypothesis"}, {"id": "c15331c8-86b5-490d-9309-db5c6b705231", "type": "concept", "title": "Alternative hypothesis"}, {"id": "6db32217-849d-43db-8ef2-1b1d7f98a041", "type": "concept", "title": "Test statistic"}, {"id": "2955c59c-8721-4f9c-a493-57c86256101a", "type": "concept", "title": "p-value"}, {"id": "d52e02d5-8db6-49ff-890f-4588637abf7a", "type": "concept", "title": "Significance level"}]}, {"id": "553efbc4-b1a3-4b29-b31e-0c82751ebc64", "type": "subtopic", "title": "Errors and Power", "description": "This subtopic explains why studies can be wrong or underpowered.", "children": [{"id": "97d32f2b-842a-40f8-a7e6-f6e35b3b4a52", "type": "concept", "title": "Type I error"}, {"id": "361b1f0f-3eb2-4740-9df6-40afa85c6f47", "type": "concept", "title": "Type II error"}, {"id": "74c9e4aa-bd75-41f5-aa5a-845f00681ff8", "type": "concept", "title": "Power"}, {"id": "b0eac7b6-791e-450f-855b-6117760bfbdc", "type": "concept", "title": "Sample size"}, {"id": "451f6ecf-fd30-4d18-a1cf-f832ca458d81", "type": "concept", "title": "Effect size"}]}, {"id": "cfd0e099-9b6a-4afa-bbbd-822e746ebded", "type": "subtopic", "title": "Interpreting p-Values Responsibly", "description": "Students avoid common misreadings of statistical significance.", "children": [{"id": "1248af00-87d6-480d-84dd-b1ef8e9dd469", "type": "concept", "title": "Not probability the null is true"}, {"id": "94992be7-3df6-4c2d-8423-2414f6f28576", "type": "concept", "title": "Not effect size"}, {"id": "d9b4e67e-98a5-4096-ba13-1f60f2ed1a0d", "type": "concept", "title": "Multiple testing"}, {"id": "e960c8fb-de19-46a2-a561-e3c596e0533d", "type": "concept", "title": "Borderline p-values"}, {"id": "4d1c354a-b7e1-46b6-8e80-2510fd093976", "type": "concept", "title": "Pre-specified analysis"}]}]}, {"id": "0b4f821a-9b89-4d33-b4a6-fccca83018be", "type": "topic", "title": "Comparing Two Groups: z-Tests, t-Tests, Paired Designs, and Effect Sizes", "description": "Covers common comparisons for means, proportions, paired data, and clinically meaningful differences.", "children": [{"id": "01139cfe-5b03-49ac-b488-072f8a68c280", "type": "subtopic", "title": "Comparing Means", "description": "Students learn methods for continuous outcomes in two groups.", "children": [{"id": "8c9cbf81-ca73-4792-b3ef-8af33949b9ad", "type": "concept", "title": "One-sample t-test"}, {"id": "8dd8ba89-88aa-4cfe-bc09-5a1517f2d9b6", "type": "concept", "title": "Independent samples t-test"}, {"id": "34053d85-d81a-4158-97ac-798983d8e75d", "type": "concept", "title": "Paired t-test"}, {"id": "70ae1e6e-b967-4dff-8eb6-a6